INSERT INTO prof VALUES
  (8954, $$Youm7$$, $$The Egyptian Company for Press, Publication and Advertising, détenue par United Media Services (ex-Egyptian Media Group)$$, $$United Media Services (ex-Egyptian Media Group), contrôlée par les Renseignements généraux via Eagle Capital$$, ARRAY['government_aligned']::text[], NULL, $$Fondé en 2008 comme hebdomadaire par l’homme d’affaires Walid Moustafa, quotidien depuis mai 2011. Ahmed Abu Hashima en devient le principal investisseur fin 2012 ; Eagle Capital rachète sa participation en décembre 2017.$$, $$Fait partie des titres d’United Media Services, que RSF et State Media Monitor décrivent comme contrôlée par les services de renseignement. Sa couverture politique est critiquée depuis 2011 (appels au boycott, accusations de fausses nouvelles). Fil d’actualité à très fort volume.$$, 'high', $$Propriété et chaîne de contrôle documentées par Media Ownership Monitor (2018), State Media Monitor (2026) et Wikipédia (2020).$$, $$[{"url": "https://egypt.mom-rsf.org/en/media/detail/outlet/al-youm-al-sabea/", "note": "Fondé en 2008 par Walid Moustafa ; Abu Hashima principal investisseur fin 2012 ; propriété de l’Egyptian Company for Press, Publication and Advertising (Egyptian Media Group), contrôlée par les Renseignements généraux via Eagle Capital (données 2018)", "category": "media_research", "accessed_at": "2026-10-15"}, {"url": "https://egypt.mom-rsf.org/en/owners/companies/detail/company/company/show/egyptian-media-group/", "note": "Egyptian Media Group détenue par Eagle Capital, société d’investissement d’État appartenant aux Renseignements généraux (données 2018)", "category": "media_research", "accessed_at": "2026-10-15"}, {"url": "https://statemediamonitor.com/2026/06/egyptian-media-group-emg/", "note": "Youm7 listé parmi les titres imprimés et numériques du groupe ; contrôle ultime par l’appareil sécuritaire via Eagle Capital (juin 2026)", "category": "media_research", "accessed_at": "2026-10-15"}, {"url": "https://en.wikipedia.org/wiki/Youm7", "note": "Hebdomadaire 2008, quotidien 2011 ; propriété d’Egyptian Media Group / United Media Services en 2020 ; controverses sur sa couverture", "category": "reference", "accessed_at": "2026-10-15"}]$$::jsonb, false);
DO $$
DECLARE bad int; n int;
BEGIN
  -- Each target must be the Egyptian publisher of that name, and must not have a profile yet.
  SELECT count(*) INTO bad FROM prof x
   WHERE NOT EXISTS (SELECT 1 FROM publishers p JOIN countries c ON c.id = p.country_id
                      WHERE p.id = x.publisher_id AND p.name = x.name AND c.iso_code = 'EG')
      OR EXISTS (SELECT 1 FROM editorial_profiles e WHERE e.publisher_id = x.publisher_id);
  IF bad > 0 THEN RAISE EXCEPTION '% of 1 publishers are not the expected Egyptian outlet or already have a profile - nothing changed', bad; END IF;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  SELECT publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, DATE '2026-10-15', DATE '2026-10-15', DATE '2026-10-15', review_required FROM prof;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'inserted %, expected 1', n; END IF;
END $$;
SELECT 'profile|' || p.id || '|' || p.name || '|' || array_to_string(e.classification_tags, ',') || '|' || e.confidence || '|review ' || e.review_required
       || '|' || jsonb_array_length(e.evidence_sources) || ' sources'
  FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id WHERE e.publisher_id IN (8954) ORDER BY p.id;
SELECT 'egypt|' || count(e.id) || ' of ' || count(*) || ' Egyptian publishers have a profile'
